float StaFloorZ(int32 Floor)
{
    // The pooled-light classifier probes floors8..1. STA has only0/1; higher probes must not alias its ground floor.
    if(HouseStadiumDetail::Enabled()&&HouseStadiumDetail::Step()>=6&&Floor>1)return FLT_MAX;
    return Floor == 1 ? StaPBFloor : StaFloor;
}

D.FloorZ = &StaFloorZ;
// Locker lights are185cm above the ground floor; keep their anchors on that floor.
if(HouseStadiumDetail::Enabled()&&HouseStadiumDetail::Step()>=6)D.LightAnchorFloorOffset=185.f;

for (const float Z : { 200.f, 650.f, 1100.f }) Out.Add(FVector(StaTwX0 + 188.f, (StaTwY0 + StaTwY1) * .5f, Z));   // over the east flights, not the gap between them
// Existing six-light pool: the upper landing also needs an anchor classified on the press-box floor.
if(HouseStadiumDetail::Enabled()&&HouseStadiumDetail::Step()>=6)Out.Add(FVector(StaTwX0+188.f,(StaTwY0+StaTwY1)*.5f,StaPBFloor+250.f));
